-- ACCOUNT TAKEOVER (ATO)
-- Attack: someone with the customer's leaked password logs in, locks the owner out, and spends.
-- The owner is the victim, so the goal is to stop the session, not to ban the account.
--
-- Anchor: a successful login that is unusual for this account (a device it has never used, a
-- country it has never logged in from, or a login right after an impossible-travel hop).
-- Signals in the 48 hours AFTER that anchor, made from the anchor device:
--   new device / new country    the attacker is not on the owner's hardware or in their country
--   impossible travel           > 900 km/h between consecutive logins (and > 500 km apart)
--   password reset              locks the real owner out
--   email change after reset    cuts the owner off from recovery and alerts (the strongest tell)
--   payment method add          the attacker's own or a stolen card
--   high-value purchase         upgrade or $100+ charge: the monetization step
--   device on 3+ accounts       credential-stuffing crews reuse the same machines
-- Legit lookalikes get one or two of these (a traveler: new country; a new phone: new device and
-- maybe a reset) but not the ordered chain from one device.
--
-- Score (0 to 100): new device 10 + new country 15 + impossible travel 20 + reset 10
--                   + email change after reset 15 + card add 10 + purchase 10 + shared device 10.
-- The first 14 days of login history are warm-up only: with no history, every device looks new.
WITH history_start AS (
    SELECT min(ts) + INTERVAL 14 DAY AS warm FROM {{ source('raw', 'logins') }}
),
ordered AS (  -- "new" means never seen in a SUCCESSFUL login: failed guesses don't make a device trusted
    SELECT l.*,
           coalesce(count(*) FILTER (WHERE success) OVER (
               PARTITION BY user_id, device_id ORDER BY ts
               ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING), 0) = 0 AS first_device_use,
           coalesce(count(*) FILTER (WHERE success) OVER (
               PARTITION BY user_id, country ORDER BY ts
               ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING), 0) = 0 AS first_country_use,
           lag(ts)  OVER w AS prev_ts,
           lag(lat) OVER w AS prev_lat,
           lag(lon) OVER w AS prev_lon
    FROM {{ source('raw', 'logins') }} l
    WINDOW w AS (PARTITION BY user_id ORDER BY ts)
),
flags AS (
    SELECT o.*, u.country AS home_country,
           o.first_device_use AND o.device_id IS DISTINCT FROM u.signup_device_id AS new_device,
           o.first_country_use AND o.country <> u.country                        AS new_country,
           coalesce(o.prev_ts IS NOT NULL
                    AND haversine_km(o.prev_lat, o.prev_lon, o.lat, o.lon) > 500
                    AND travel_speed_kmh(o.prev_lat, o.prev_lon, o.prev_ts, o.lat, o.lon, o.ts) > 900,
                    false)                                                       AS impossible_hop
    FROM ordered o
    JOIN {{ source('raw', 'users') }} u USING (user_id)
),
hops AS (
    SELECT user_id, ts FROM flags WHERE impossible_hop
),
anchors AS (
    SELECT f.user_id, f.login_id, f.ts AS anchor_ts, f.device_id AS anchor_device, f.ip AS anchor_ip,
           f.country AS anchor_country, f.home_country, f.new_device, f.new_country,
           EXISTS (SELECT 1 FROM hops h
                   WHERE h.user_id = f.user_id AND h.ts BETWEEN f.ts - INTERVAL 2 HOUR AND f.ts) AS impossible_travel
    FROM flags f, history_start hs
    WHERE f.success AND f.ts >= hs.warm
      AND (f.new_device OR f.new_country OR f.impossible_hop)
),
sequence AS (
    SELECT a.login_id,
           min(e.ts) FILTER (WHERE e.event_type = 'password_reset')     AS reset_ts,
           min(e.ts) FILTER (WHERE e.event_type = 'email_change')       AS email_change_ts,
           min(e.ts) FILTER (WHERE e.event_type = 'payment_method_add') AS card_add_ts,
           min(e.ts) FILTER (WHERE e.event_type = 'plan_change')        AS plan_change_ts
    FROM anchors a
    JOIN {{ source('raw', 'account_events') }} e
      ON e.user_id = a.user_id AND e.device_id = a.anchor_device
     AND e.ts > a.anchor_ts AND e.ts <= a.anchor_ts + INTERVAL 48 HOUR
    GROUP BY a.login_id
),
spend AS (
    SELECT a.login_id, max(t.amount) AS max_charge, sum(t.amount) AS charged_usd
    FROM anchors a
    JOIN {{ source('raw', 'transactions') }} t
      ON t.user_id = a.user_id AND t.device_id = a.anchor_device
     AND t.txn_type = 'charge' AND t.result = 'approved'
     AND t.ts > a.anchor_ts AND t.ts <= a.anchor_ts + INTERVAL 48 HOUR
    GROUP BY a.login_id
),
device_reach AS (
    SELECT device_id, count(DISTINCT user_id) AS accounts_on_device FROM {{ source('raw', 'logins') }} WHERE success GROUP BY 1
),
account_value AS (
    SELECT u.user_id, u.account_age_days,
           coalesce(sum(t.amount) FILTER (WHERE t.txn_type = 'charge' AND t.result = 'approved'), 0) AS lifetime_usd
    FROM {{ source('raw', 'users') }} u LEFT JOIN {{ source('raw', 'transactions') }} t USING (user_id)
    GROUP BY ALL
),
scored AS (
    SELECT a.*, s.reset_ts, s.email_change_ts, s.card_add_ts, s.plan_change_ts,
           coalesce(m.charged_usd, 0) AS charged_after_usd,
           d.accounts_on_device, v.account_age_days, v.lifetime_usd,
           s.email_change_ts > s.reset_ts AS email_after_reset,
           coalesce(m.max_charge >= 100, false) OR s.plan_change_ts IS NOT NULL AS monetized,
             CASE WHEN a.new_device THEN 10 ELSE 0 END
           + CASE WHEN a.new_country THEN 15 ELSE 0 END
           + CASE WHEN a.impossible_travel THEN 20 ELSE 0 END
           + CASE WHEN s.reset_ts IS NOT NULL THEN 10 ELSE 0 END
           + CASE WHEN s.email_change_ts > s.reset_ts THEN 15
                  WHEN s.email_change_ts IS NOT NULL THEN 8 ELSE 0 END
           + CASE WHEN s.card_add_ts IS NOT NULL THEN 10 ELSE 0 END
           + CASE WHEN coalesce(m.max_charge >= 100, false) OR s.plan_change_ts IS NOT NULL THEN 10 ELSE 0 END
           + CASE WHEN d.accounts_on_device >= 3 THEN 10 ELSE 0 END AS raw_score
    FROM anchors a
    LEFT JOIN sequence s USING (login_id)
    LEFT JOIN spend m USING (login_id)
    LEFT JOIN device_reach d ON d.device_id = a.anchor_device
    LEFT JOIN account_value v USING (user_id)
    QUALIFY row_number() OVER (PARTITION BY a.user_id ORDER BY raw_score DESC, a.anchor_ts) = 1
)
SELECT
    'user' AS entity_type,
    user_id AS entity_id,
    CAST(least(raw_score, 100) AS INTEGER) AS risk_score,
    list_filter([
        CASE WHEN new_device THEN 'NEW_DEVICE' END,
        CASE WHEN new_country THEN 'NEW_COUNTRY' END,
        CASE WHEN impossible_travel THEN 'IMPOSSIBLE_TRAVEL' END,
        CASE WHEN reset_ts IS NOT NULL THEN 'PASSWORD_RESET_FROM_NEW_DEVICE' END,
        CASE WHEN email_after_reset THEN 'EMAIL_CHANGE_AFTER_RESET' END,
        CASE WHEN card_add_ts IS NOT NULL THEN 'NEW_PAYMENT_METHOD' END,
        CASE WHEN monetized THEN 'HIGH_VALUE_PURCHASE' END,
        CASE WHEN accounts_on_device >= 3 THEN 'DEVICE_ON_MANY_ACCOUNTS' END
    ], lambda x: x IS NOT NULL) AS reason_codes,
    CASE WHEN risk_score >= 85 THEN 'review'
         WHEN risk_score >= 60 THEN 'step_up'
         ELSE 'allow' END AS recommended_action,
    CASE WHEN risk_score >= 85 THEN 'Kill sessions, verify owner via original email, roll back email/card changes, refund'
         WHEN risk_score >= 60 THEN 'Force MFA re-authentication and freeze email and payment changes for 72h'
         ELSE 'No action' END AS action_detail,
    anchor_ts, anchor_device, anchor_ip, anchor_country, home_country,
    reset_ts, email_change_ts, card_add_ts, charged_after_usd,
    accounts_on_device, account_age_days, lifetime_usd
FROM scored
